        merge("req-g34", "geo-1", 1, "4.000", "0", "1", "0", "1", "op-2")
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(2));
        assertThat(versionCount("geo-1")).isEqualTo(2);

        delete("req-g35", "geo-1", 2, "op-3").andExpect(status().isOk());
