        create("req-g11", "geo-1", "1", "1", "1", "0", "1", "op-1").andExpect(status().isConflict());
        getCurrent("geo-1").andExpect(jsonPath("$.x").value("0"));
        assertThat(versionCount("geo-1")).isEqualTo(1);
    }

